class DocFileHandler:
    """
    This is a class that handles Word documents and provides functionalities for reading, writing, and modifying the content of Word documents.
    """

    def __init__(self, file_path):
        """
        Initializes the DocFileHandler object with the specified file path.
        :param file_path: str, the path to the Word document file.
        """
        self.file_path = file_path

    def read_text(self):
        """
        Reads the content of a Word document and returns it as a string.
        :return: str, the content of the Word document.
        """
        try:
            doc = Document(self.file_path)
            paragraphs = [p.text for p in doc.paragraphs]
            return "\n".join(paragraphs)
        except Exception:
            return ""

    def write_text(self, content, font_size=12, alignment='left'):
        """
        Writes the specified content to a Word document.
        :param content: str, the text content to write.
        :param font_size: int, optional, the font size of the text (default is 12).
        :param alignment: str, optional, the alignment of the text ('left', 'center', or 'right'; default is 'left').
        :return: bool, True if the write operation is successful, False otherwise.
        """
        try:
            try:
                doc = Document(self.file_path)
            except Exception:
                doc = Document()

            paragraph = doc.add_paragraph()
            run = paragraph.add_run(str(content))
            run.font.size = Pt(font_size)
            paragraph.alignment = self._get_alignment_value(alignment)

            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def add_heading(self, heading, level=1):
        """
        Adds a heading to the Word document.
        :param heading: str, the text of the heading.
        :param level: int, optional, the level of the heading (1, 2, 3, etc.; default is 1).
        :return: bool, True if the heading is successfully added, False otherwise.
        """
        try:
            try:
                doc = Document(self.file_path)
            except Exception:
                doc = Document()

            lvl = int(level)
            if lvl < 0:
                lvl = 0
            if lvl > 9:
                lvl = 9

            doc.add_heading(str(heading), level=lvl)
            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def add_table(self, data):
        """
        Adds a table to the Word document with the specified data.
        :param data: list of lists, the data to populate the table.
        :return: bool, True if the table is successfully added, False otherwise.
        """
        try:
            if not data or not isinstance(data, list):
                return False
            if not all(isinstance(row, (list, tuple)) for row in data):
                return False

            max_cols = max((len(row) for row in data), default=0)
            if max_cols == 0:
                return False

            try:
                doc = Document(self.file_path)
            except Exception:
                doc = Document()

            table = doc.add_table(rows=len(data), cols=max_cols)

            for i, row_data in enumerate(data):
                for j in range(max_cols):
                    value = row_data[j] if j < len(row_data) else ""
                    table.cell(i, j).text = str(value)

            doc.save(self.file_path)
            return True
        except Exception:
            return False

    def _get_alignment_value(self, alignment):
        """
        Returns the alignment value corresponding to the given alignment string.
        :param alignment: str, the alignment string ('left', 'center', or 'right').
        :return: int, the alignment value.
        """
        alignment_map = {
            "left": WD_PARAGRAPH_ALIGNMENT.LEFT,
            "center": WD_PARAGRAPH_ALIGNMENT.CENTER,
            "right": WD_PARAGRAPH_ALIGNMENT.RIGHT,
            "justify": WD_PARAGRAPH_ALIGNMENT.JUSTIFY,
        }
        if alignment is None:
            return WD_PARAGRAPH_ALIGNMENT.LEFT
        return alignment_map.get(str(alignment).strip().lower(), WD_PARAGRAPH_ALIGNMENT.LEFT)

class Interpolation:
    """
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    """

    def __init__(self):
        pass

    @staticmethod
    def interpolate_1d(x, y, x_interp):
        """
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :return: The y-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_1d([1, 2, 3], [1, 2, 3], [1.5, 2.5])
        [1.5, 2.5]
        """
        if len(x) != len(y):
            raise ValueError("x and y must have the same length.")
        if len(x) < 2:
            raise ValueError("At least two data points are required for interpolation.")

        # Ensure x is strictly increasing
        for i in range(len(x) - 1):
            if x[i + 1] <= x[i]:
                raise ValueError("x must be strictly increasing.")

        def interp_point(xp):
            if xp < x[0] or xp > x[-1]:
                raise ValueError(f"Interpolation point {xp} is out of bounds [{x[0]}, {x[-1]}].")

            # Exact match shortcut
            for i, xv in enumerate(x):
                if xp == xv:
                    return float(y[i])

            # Find interval [x[i], x[i+1]]
            for i in range(len(x) - 1):
                x0, x1 = x[i], x[i + 1]
                if x0 <= xp <= x1:
                    y0, y1 = y[i], y[i + 1]
                    t = (xp - x0) / (x1 - x0)
                    return float(y0 + t * (y1 - y0))

            # Should never happen due to bounds check
            raise RuntimeError("Failed to interpolate point.")

        return [interp_point(xp) for xp in x_interp]

    @staticmethod
    def interpolate_2d(x, y, z, x_interp, y_interp):
        """
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, list.
        :param y: The y-coordinate of the data point, list.
        :param z: The z-coordinate of the data point, list.
        :param x_interp: The x-coordinate of the interpolation point, list.
        :param y_interp: The y-coordinate of the interpolation point, list.
        :return: The z-coordinate of the interpolation point, list.
        >>> interpolation = Interpolation()
        >>> interpolation.interpolate_2d([1, 2, 3], [1, 2, 3], [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [1.5, 2.5], [1.5, 2.5])
        [3.0, 7.0]
        """
        if len(x) < 2 or len(y) < 2:
            raise ValueError("x and y must each contain at least two points.")
        if len(z) != len(y) or any(len(row) != len(x) for row in z):
            raise ValueError("z must have shape (len(y), len(x)).")
        if len(x_interp) != len(y_interp):
            raise ValueError("x_interp and y_interp must have the same length.")

        # Ensure x and y are strictly increasing
        for i in range(len(x) - 1):
            if x[i + 1] <= x[i]:
                raise ValueError("x must be strictly increasing.")
        for j in range(len(y) - 1):
            if y[j + 1] <= y[j]:
                raise ValueError("y must be strictly increasing.")

        def find_interval(arr, v):
            if v < arr[0] or v > arr[-1]:
                raise ValueError(f"Interpolation point {v} is out of bounds [{arr[0]}, {arr[-1]}].")

            # Exact endpoint
            if v == arr[-1]:
                return len(arr) - 2, len(arr) - 1

            for k in range(len(arr) - 1):
                if arr[k] <= v <= arr[k + 1]:
                    return k, k + 1
            raise RuntimeError("Failed to find interpolation interval.")

        results = []
        for xp, yp in zip(x_interp, y_interp):
            i0, i1 = find_interval(x, xp)
            j0, j1 = find_interval(y, yp)

            x0, x1 = x[i0], x[i1]
            y0, y1 = y[j0], y[j1]

            z00 = z[j0][i0]
            z10 = z[j0][i1]
            z01 = z[j1][i0]
            z11 = z[j1][i1]

            tx = 0.0 if x1 == x0 else (xp - x0) / (x1 - x0)
            ty = 0.0 if y1 == y0 else (yp - y0) / (y1 - y0)

            # Bilinear interpolation
            z0 = z00 * (1 - tx) + z10 * tx
            z1 = z01 * (1 - tx) + z11 * tx
            zp = z0 * (1 - ty) + z1 * ty

            results.append(float(zp))

        return results

class NumberConverter:
    """
    The class allows to convert  decimal to binary, octal and hexadecimal repectively and contrarily
    """

    @staticmethod
    def decimal_to_binary(decimal_num):
        """
        Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        >>> NumberConverter.decimal_to_binary(42423)
        '1010010110110111'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an integer")
        return format(decimal_num, "b")

    @staticmethod
    def binary_to_decimal(binary_num):
        """
        Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        >>> NumberConverter.binary_to_decimal('1010010110110111')
        42423
        """
        if not isinstance(binary_num, str):
            raise TypeError("binary_num must be a string")
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """
        Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        >>> NumberConverter.decimal_to_octal(42423)
        '122667'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an integer")
        return format(decimal_num, "o")

    @staticmethod
    def octal_to_decimal(octal_num):
        """
        Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        >>> NumberConverter.octal_to_decimal('122667')
        42423
        """
        if not isinstance(octal_num, str):
            raise TypeError("octal_num must be a string")
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """
        Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return hex_num: str, the hex representation of an integer.
        >>> NumberConverter.decimal_to_hex(42423)
        'a5b7'
        """
        if not isinstance(decimal_num, int):
            raise TypeError("decimal_num must be an integer")
        return format(decimal_num, "x")

    @staticmethod
    def hex_to_decimal(hex_num):
        """
        Convert a number from hex format to decimal format.
        :param hex_num: str, hex num
