            raise TypeError("hex_num must be a string")
        return int(hex_num, 16)

class NumericEntityUnescaper:
    """
    This is a class that provides functionality to replace numeric entities with their corresponding characters in a given string.
    """

    def __init__(self):
        pass

    def replace(self, string):
        """
        Replaces numeric character references (HTML entities) in the input string with their corresponding Unicode characters.
        :param string: str, the input string containing numeric character references.
        :return: str, the input string with numeric character references replaced with their corresponding Unicode characters.
        >>> unescaper = NumericEntityUnescaper()
        >>> unescaper.replace("&#65;&#66;&#67;")
        'ABC'

        """
        if not isinstance(string, str):
            raise TypeError("string must be of type str")

        result = []
        i = 0
        n = len(string)

        while i < n:
            if string[i] == "&" and i + 2 < n and string[i + 1] == "#":
                j = i + 2
                base = 10

                # Hex form: &#x...; or &#X...;
                if j < n and string[j] in ("x", "X"):
                    base = 16
                    j += 1

                start_digits = j

                # Consume valid digits based on base
                if base == 16:
                    while j < n and self.is_hex_char(string[j]):
                        j += 1
                else:
                    while j < n and string[j].isdigit():
                        j += 1

                # Must have at least one digit and end with ';'
                if j > start_digits and j < n and string[j] == ";":
                    num_str = string[start_digits:j]
                    try:
                        codepoint = int(num_str, base)
                        # Valid Unicode scalar range
                        if 0 <= codepoint <= 0x10FFFF:
                            result.append(chr(codepoint))
                            i = j + 1
                            continue
                    except (ValueError, OverflowError):
                        pass

            # Not a valid numeric entity; keep original char
            result.append(string[i])
            i += 1

        return "".join(result)

    @staticmethod
    def is_hex_char(char):
        """
        Determines whether a given character is a hexadecimal digit.
        :param char: str, the character to check.
        :return: bool, True if the character is a hexadecimal digit, False otherwise.
        >>> NumericEntityUnescaper.is_hex_char('a')
        True

        """
        return isinstance(char, str) and len(char) == 1 and (
            "0" <= char <= "9" or "a" <= char.lower() <= "f"
        )

class SQLQueryBuilder:
    """
    This class provides to build SQL queries, including SELECT, INSERT, UPDATE, and DELETE statements.
    """

    @staticmethod
    def _format_value(value):
        return f"'{value}'"

    @staticmethod
    def _build_where(where):
        if not where:
            return ""
        conditions = [f"{key}={SQLQueryBuilder._format_value(value)}" for key, value in where.items()]
        return " WHERE " + " AND ".join(conditions)

    @staticmethod
    def select(table, columns='*', where=None):
        """
        Generate the SELECT SQL statement from the given parameters.
        :param table: str, the query table in database.
        :param columns: list of str, ['col1', 'col2'].
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        return query: str, the SQL query statement.
        >>> SQLQueryBuilder.select('table1', columns = ["col1","col2"], where = {"age": 15})
        "SELECT col1, col2 FROM table1 WHERE age='15'"
        """
        if isinstance(columns, (list, tuple)):
            col_part = ", ".join(columns)
        else:
            col_part = columns
        return f"SELECT {col_part} FROM {table}" + SQLQueryBuilder._build_where(where)

    @staticmethod
    def insert(table, data):
        """
        Generate the INSERT SQL statement from the given parameters.
        :param table: str, the table to be inserted in database.
        :param data: dict, the key and value in SQL insert statement
        :return query: str, the SQL insert statement.
        >>> SQLQueryBuilder.insert('table1', {'name': 'Test', 'age': 14})
        "INSERT INTO table1 (name, age) VALUES ('Test', '14')"
        """
        columns = ", ".join(data.keys())
        values = ", ".join(SQLQueryBuilder._format_value(v) for v in data.values())
        return f"INSERT INTO {table} ({columns}) VALUES ({values})"

    @staticmethod
    def delete(table, where=None):
        """
        Generate the DELETE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with DELETE operation in database
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        :return query: str, the SQL delete statement.
        >>> SQLQueryBuilder.delete('table1', {'name': 'Test', 'age': 14})
        "DELETE FROM table1 WHERE name='Test' AND age='14'"
        """
        return f"DELETE FROM {table}" + SQLQueryBuilder._build_where(where)

    @staticmethod
    def update(table, data, where=None):
        """
        Generate the UPDATE SQL statement from the given parameters.
        :param table: str, the table that will be excuted with UPDATE operation in database
        :param data: dict, the key and value in SQL update statement
        :param where: dict, {key1: value1, key2: value2 ...}. The query condition.
        >>> SQLQueryBuilder.update('table1', {'name': 'Test2', 'age': 15}, where = {'name':'Test'})
        "UPDATE table1 SET name='Test2', age='15' WHERE name='Test'"
        """
        set_part = ", ".join(f"{key}={SQLQueryBuilder._format_value(value)}" for key, value in data.items())
        return f"UPDATE {table} SET {set_part}" + SQLQueryBuilder._build_where(where)

