        """
        if textnum is None:
            raise ValueError("Input cannot be None")

        textnum = textnum.strip().lower()
        if not textnum:
            raise ValueError("Input cannot be empty")

        if not self.is_valid_input(textnum):
            raise ValueError(f"Illegal word in input: {textnum!r}")

        current = result = 0
        words = textnum.replace("-", " ").split()

        for word in words:
            if word in self.ordinal_words:
                scale, increment = (1, self.ordinal_words[word])
            else:
                if word not in self.numwords:
                    # Try ordinal normalization (e.g., twentieth -> twenty, hundredth -> hundred)
                    normalized = None
                    for ending, replacement in self.ordinal_endings:
                        if word.endswith(ending):
                            candidate = word[:-len(ending)] + replacement
                            if candidate in self.numwords:
                                normalized = candidate
                                break
                    if normalized is None:
                        raise ValueError(f"Illegal word: {word!r}")
                    scale, increment = self.numwords[normalized]
                else:
                    scale, increment = self.numwords[word]

            current = current * scale + increment
            if scale > 100:
                result += current
                current = 0

        return str(result + current)

    def is_valid_input(self, textnum):
        """
        Check if the input text contains only valid words that can be converted into numbers.
        :param textnum: The input text containing words representing numbers.
        :return: True if input is valid, False otherwise.
        >>> w2n = Words2Numbers()
        >>> w2n.is_valid_input("thirty-two")
        False
        """
        if textnum is None:
            return False

        textnum = textnum.strip().lower()
        if not textnum:
            return False

        for word in textnum.replace("-", " ").split():
            if word in self.numwords or word in self.ordinal_words:
                continue

            # Allow ordinals that can be normalized by configured endings
            valid_ordinal = False
            for ending, replacement in self.ordinal_endings:
                if word.endswith(ending):
                    candidate = word[:-len(ending)] + replacement
                    if candidate in self.numwords:
                        valid_ordinal = True
                        break

            if not valid_ordinal:
                return False

        return True
